svg.script:
const bias = document.getElementById("bias");
const step = document.getElementById("step");
const play = document.getElementById("play");
const rows = Array.from(document.querySelectorAll(".trajectory"));
const maxStep = Number(step.max);
const trackWidth = document.querySelector("#lanes rect").width.baseVal.value;
let timer;

// The student independently chooses the text branch at both steps with probability p.
// Mirror descent updates its log odds using d(KL)/dp, with the same step size for both objectives.
function fit(initial, steps, reverse) {
  let logOdds = Math.log(initial / (1 - initial));
  for (let t = 0; t < steps; t++) {
    const p = 1 / (1 + Math.exp(-logOdds));
    const gradient = reverse
      ? 2 * (logOdds + (1 - 2 * p) * Math.log(0.49 / 0.01))
      : (2 * p - 1) / (p * (1 - p));
    logOdds -= 0.2 * gradient;
  }
  const p = 1 / (1 + Math.exp(-logOdds));
  return [p * p, 2 * p * (1 - p), (1 - p) ** 2];
}

function draw() {
  const t = Number(step.value);
  for (const method of ["m", "i"]) {
    const probabilities = fit(Number(bias.value), t, method === "i");
    rows.forEach((row, index) => {
      const probability = probabilities[index];
      row.querySelector(".bar." + method).setAttribute("width", trackWidth * probability);
      row.querySelector(".value." + method).textContent = (100 * probability).toFixed(1) + "%";
    });
  }
  document.getElementById("count").value = t + " / " + maxStep;
  play.textContent = timer ? "暂停" : t === maxStep ? "重播" : "播放";
}

function pause() {
  clearInterval(timer);
  timer = undefined;
}
function scrub() {
  pause();
  draw();
}
step.addEventListener("input", scrub);
bias.addEventListener("change", scrub);
play.addEventListener("click", () => {
  if (timer) {
    scrub();
    return;
  }
  if (Number(step.value) === maxStep) step.value = 0;
  timer = setInterval(() => {
    step.stepUp();
    if (Number(step.value) === maxStep) pause();
    draw();
  }, 210);
  draw();
});
document.querySelector(".controls").hidden = false;
draw();
